// src/modules/talent-match/TalentMatch.js
import React, { useMemo, useState } from "react";
import Sidebar from "../../components/Sidebar";
import Header from "../../components/Header";
import "./TalentMatch.css";

const readJson = (key, fallback = []) => {
  try {
    return JSON.parse(localStorage.getItem(key) || JSON.stringify(fallback));
  } catch (e) {
    return fallback;
  }
};

function TalentMatch() {
  // data sources
  const jobs = readJson("jobs", []);
  const projects = readJson("projects", []);
  const freelancerProfiles = readJson("freelancerProfiles", []);
  const jobSeekerProfiles = readJson("jobSeekerProfiles", []);
  const companyProfiles = readJson("companyProfiles", []);

  // determine role like Dashboard does
  let role = "guest";
  try {
    const cu = JSON.parse(localStorage.getItem("currentUser") || "null");
    if (cu && cu.role) role = cu.role;
    else if (cu && cu.email) {
      const email = cu.email;
      if (companyProfiles.find(c => c.user_id === email || c.company_name === email)) role = "company";
      else if (freelancerProfiles.find(f => f.email === email)) role = "freelancer";
      else if (jobSeekerProfiles.find(j => j.email === email)) role = "jobseeker";
    }
  } catch (e) {
    role = "guest";
  }

  // common state
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("All Status"); // only relevant for company
  const [scoreFilter, setScoreFilter] = useState("All Scores");
  const [workModeFilter, setWorkModeFilter] = useState("All Locations / Work Types");

  // dummy candidates for company view (you can replace with real data later)
  const dummyCandidates = readJson("candidates", [
    {
      id: 1,
      name: "James Wilson",
      skills: "Java, Spring, Microservices",
      match: 82,
      status: "Interview Scheduled",
      email: "j.wilson@email.com",
      phone: "+1 (555) 123-4567",
      location: "Chicago, IL",
      experience: "5 years",
      aiSummary:
        "Strong technical background in Java & Microservices. Good problem-solver and team fit.",
    },
    {
      id: 2,
      name: "Aisha Khan",
      skills: "React, TypeScript, Node.js",
      match: 90,
      status: "Under Review",
      email: "a.khan@email.com",
      phone: "+92 300 0000000",
      location: "Karachi, PK",
      experience: "4 years",
      aiSummary: "Frontend specialist with strong UI/UX and component architecture experience.",
    },
  ]);

  // filtered candidates (company)
  const filteredCandidates = useMemo(() => {
    const q = searchTerm.trim().toLowerCase();
    return dummyCandidates.filter((c) => {
      const matchesQuery =
        !q ||
        c.name.toLowerCase().includes(q) ||
        c.skills.toLowerCase().includes(q) ||
        c.location.toLowerCase().includes(q);
      const matchesStatus = statusFilter === "All Status" || (c.status || "") === statusFilter;
      // score filter quick mapping:
      const scoreOk =
        scoreFilter === "All Scores" ||
        (scoreFilter === "90%+ Match" && c.match >= 90) ||
        (scoreFilter === "80%+ Match" && c.match >= 80) ||
        (scoreFilter === "70%+ Match" && c.match >= 70);
      return matchesQuery && matchesStatus && scoreOk;
    });
  }, [searchTerm, statusFilter, scoreFilter, dummyCandidates]);

  // For freelancers/jobseekers: top jobs/projects and search
  const randomTopJobsProjects = useMemo(() => {
    const pool = [...jobs, ...projects].map((it) => ({
      title: it.job_title || it.project_title || "Untitled",
      description: it.job_description || it.project_description || "",
      domain: it.preferred_domain || it.domain || "General",
      id: it.id || Date.now() + Math.random(),
    }));
    const shuffled = pool.sort(() => 0.5 - Math.random());
    return shuffled.slice(0, 5);
  }, [jobs, projects]);

  const [searchResults, setSearchResults] = useState([]);

  const handleSearchJobsProjects = (e) => {
    e && e.preventDefault();
    const q = searchTerm.trim().toLowerCase();
    if (!q) {
      setSearchResults([]);
      return;
    }
    const matchedJobs = jobs
      .filter((j) => (j.preferred_domain || j.domain || "").toLowerCase().includes(q) || (j.required_skills || "").toLowerCase().includes(q))
      .slice(0, 5)
      .map((j) => ({ ...j, kind: "job" }));
    const matchedProjects = projects
      .filter((p) => (p.domain || "").toLowerCase().includes(q) || (p.required_skills || "").toLowerCase().includes(q))
      .slice(0, 5)
      .map((p) => ({ ...p, kind: "project" }));
    setSearchResults([...matchedJobs, ...matchedProjects]);
  };

  // company helper: schedule interview (dummy)
  const scheduleInterview = (candidate) => {
    alert(`Schedule interview for ${candidate.name} — open modal / calendar here (stub).`);
  };

  return (
    <div className="talentmatch-container">
      <Sidebar />
      <div className="talentmatch-main">
        <Header />

        <div className="talentmatch-content">
          {/* Page Title */}
          <div className="talentmatch-header-section">
            <div className="talentmatch-title">
              <h1>{role === "company" ? "Candidates" : "Jobs & Projects"}</h1>
              <p>
                {role === "company"
                  ? "Manage and review AI-matched candidates"
                  : "Search jobs and projects matched to your skills / domain"}
              </p>
            </div>

            {/* Company-only action */}
            {role === "company" ? (
              <button className="add-candidate-btn">+ Add Candidate</button>
            ) : null}
          </div>

          {/* Top Row: left filters / search + right mini-profile (company only) */}
          <div className="talentmatch-top-row">
            {/* Left: Filters / Search (both roles but different behavior) */}
            <div className="talentmatch-filters-container" style={{ minWidth: 320 }}>
              {role === "company" ? (
                <>
                  <input
                    type="text"
                    placeholder="Search candidates by name, skills, or location..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="search-input"
                  />

                  <select
                    className="status-dropdown"
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                  >
                    <option>All Status</option>
                    <option>New Candidate</option>
                    <option>Under Review</option>
                    <option>Interview Scheduled</option>
                  </select>
                </>
              ) : (
                <>
                  <input
                    type="text"
                    placeholder="Search jobs/projects by domain, skill or location..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="search-input"
                  />
                  <select
                    className="status-dropdown"
                    value={workModeFilter}
                    onChange={(e) => setWorkModeFilter(e.target.value)}
                  >
                    <option>All Locations / Work Types</option>
                    <option>Remote</option>
                    <option>Hybrid</option>
                    <option>On-site</option>
                  </select>

                  {/* Search button for jobs/projects */}
                  <button
                    className="add-candidate-btn"
                    style={{ marginLeft: 12 }}
                    onClick={handleSearchJobsProjects}
                  >
                    Search
                  </button>
                </>
              )}
            </div>

            {/* Right: Mini-profile + details ONLY for company (scheduling) */}
            {role === "company" ? (
              <div className="mini-profile-container">
                <div className="mini-profile-header">
                  <div className="mini-profile-avatar">JW</div>
                  <div>
                    <p className="mini-profile-name">James Wilson</p>
                    <p className="mini-profile-experience">5 years Experience</p>
                  </div>
                </div>

                <div className="mini-profile-details">
                  <p>
                    <strong>AI Match:</strong> 82%
                  </p>
                  <p>
                    <strong>Email:</strong> j.wilson@email.com
                  </p>
                  <p>
                    <strong>Phone:</strong> +1 (555) 123-4567
                  </p>
                  <p>
                    <strong>Location:</strong> Chicago, IL
                  </p>
                  <p>
                    <strong>Interview:</strong> Oct 25, 2025
                  </p>
                  <p>
                    <strong>AI Summary:</strong> Strong technical background with 5 years of experience in Java, Spring,
                    Microservices.
                  </p>
                  <p>
                    <strong>Key Skills:</strong> Java, Spring, Microservices
                  </p>
                  <button className="schedule-interview-btn" onClick={() => scheduleInterview(dummyCandidates[0])}>
                    Schedule Interview
                  </button>
                </div>
              </div>
            ) : null}
          </div>

          {/* Second Row: Score + More Filters (company uses these, freelancers can still use work-mode) */}
          <div className="talentmatch-filters-second">
            {role === "company" ? (
              <>
                <select className="score-dropdown" value={scoreFilter} onChange={(e) => setScoreFilter(e.target.value)}>
                  <option>All Scores</option>
                  <option>90%+ Match</option>
                  <option>80%+ Match</option>
                  <option>70%+ Match</option>
                </select>

                <select
                  className="more-filters-dropdown"
                  value={workModeFilter}
                  onChange={(e) => setWorkModeFilter(e.target.value)}
                >
                  <option>All Locations / Work Types</option>
                  <option>Remote</option>
                  <option>Hybrid</option>
                  <option>On-site</option>
                </select>
              </>
            ) : (
              <>
                <select
                  className="score-dropdown"
                  value={workModeFilter}
                  onChange={(e) => setWorkModeFilter(e.target.value)}
                >
                  <option>All Locations / Work Types</option>
                  <option>Remote</option>
                  <option>Hybrid</option>
                  <option>On-site</option>
                </select>
              </>
            )}
          </div>

          {/* Main List Area */}
          <div className="candidates-list">
            {role === "company" ? (
              filteredCandidates.length === 0 ? (
                <p style={{ color: "#666", textAlign: "center", marginTop: "20px" }}>No candidates to display</p>
              ) : (
                filteredCandidates.map((candidate) => (
                  <div className="candidate-card" key={candidate.id}>
                    <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                      <div className="candidate-placeholder">{candidate.name.split(" ").map((p) => p[0]).join("").slice(0,2)}</div>
                      <div style={{ minWidth: 260 }}>
                        <p className="candidate-name">{candidate.name}</p>
                        <p className="candidate-skills">{candidate.skills}</p>
                        <p className="small-muted" style={{ marginTop: 6 }}>{candidate.location} • {candidate.experience}</p>
                      </div>
                    </div>

                    <div className="candidate-match">
                      <p className="match-percent">{candidate.match}% Match</p>
                      <p className={`status ${candidate.status.replace(" ", "-").toLowerCase()}`}>{candidate.status}</p>
                      <div style={{ marginTop: 8 }}>
                        <button className="btn-primary" style={{ marginRight: 8 }} onClick={() => scheduleInterview(candidate)}>
                          Schedule
                        </button>
                        <button
                          className="btn-primary"
                          onClick={() => alert(`Open candidate details for ${candidate.name} (stub).`)}
                          style={{ background: "#fff", color: "#333", border: "1px solid #e6e9ef" }}
                        >
                          View
                        </button>
                      </div>
                    </div>
                  </div>
                ))
              )
            ) : (
              // freelancer / jobseeker view: show top jobs/projects and search results
              <>
                {searchResults.length > 0 ? (
                  <>
                    <h3 style={{ marginTop: 6 }}>Search results (top 5)</h3>
                    <div className="list-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(260px,1fr))", gap: 12 }}>
                      {searchResults.map((r) => (
                        <div key={r.id || r.job_title} className="dashboard-item-card" style={{ padding: 12 }}>
                          <strong>{r.job_title || r.project_title}</strong>
                          <p className="muted">{(r.job_description || r.project_description || "").slice(0, 120)}...</p>
                          <p className="small-muted">{r.preferred_domain || r.domain}</p>
                        </div>
                      ))}
                    </div>
                  </>
                ) : (
                  <>
                    <h3 style={{ marginTop: 6 }}>Top 5 jobs & projects</h3>
                    <div className="list-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(260px,1fr))", gap: 12 }}>
                      {randomTopJobsProjects.length === 0 ? (
                        <p style={{ color: "#666" }}>No jobs or projects available yet.</p>
                      ) : (
                        randomTopJobsProjects.map((item) => (
                          <div key={item.id} className="dashboard-item-card" style={{ padding: 12 }}>
                            <strong>{item.title}</strong>
                            <p className="muted">{(item.description || "").slice(0, 120)}...</p>
                            <p className="small-muted">{item.domain}</p>
                          </div>
                        ))
                      )}
                    </div>
                  </>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default TalentMatch;
